void install_SRV6_SIDS_NODE(void)

{
	unsigned node_id = SRV6_SIDS_NODE;
	struct cmd_node *node;

	assert(node_id < vector_active(cmdvec));
	node = vector_slot(cmdvec, node_id);
	assert(node);
	assert(vector_active(node->cmdgraph->nodes) == 1);
	graph_delete_node(node->cmdgraph, vector_slot(node->cmdgraph->nodes, 0));
	vector_free(node->cmdgraph->nodes);
	node->cmdgraph->nodes = &gvec_SRV6_SIDS_NODE;
	vector_set(node->cmd_vector, &no_srv6_sid_cmd_vtysh);
	vector_set(node->cmd_vector, &srv6_sid_cmd_vtysh);
}

