extern void install_BFD_PEER_NODE(void);

void install_BFD_PEER_NODE(void)

{
	unsigned node_id = BFD_PEER_NODE;
	struct cmd_node *node;

	assert(node_id < vector_active(cmdvec));
	node = vector_slot(cmdvec, node_id);
	assert(node);
	assert(vector_active(node->cmdgraph->nodes) == 1);
	graph_delete_node(node->cmdgraph, vector_slot(node->cmdgraph->nodes, 0));
	vector_free(node->cmdgraph->nodes);
	node->cmdgraph->nodes = &gvec_BFD_PEER_NODE;
	vector_set(node->cmd_vector, &bfd_peer_auth_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_auth_meticulous_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_echo_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_echo_interval_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_echo_receive_interval_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_echo_transmit_interval_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_log_session_changes_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_minimum_ttl_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_mult_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_passive_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_profile_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_rx_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_shutdown_cmd_vtysh);
	vector_set(node->cmd_vector, &bfd_peer_tx_cmd_vtysh);
	vector_set(node->cmd_vector, &no_bfd_peer_minimum_ttl_cmd_vtysh);
}

