extern void install_VTY_NODE(void);

void install_VTY_NODE(void)

{
	unsigned node_id = VTY_NODE;
	struct cmd_node *node;

	assert(node_id < vector_active(cmdvec));
	node = vector_slot(cmdvec, node_id);
	assert(node);
	assert(vector_active(node->cmdgraph->nodes) == 1);
	graph_delete_node(node->cmdgraph, vector_slot(node->cmdgraph->nodes, 0));
	vector_free(node->cmdgraph->nodes);
	node->cmdgraph->nodes = &gvec_VTY_NODE;
	vector_set(node->cmd_vector, &exec_timeout_min_cmd_vtysh);
	vector_set(node->cmd_vector, &exec_timeout_sec_cmd_vtysh);
	vector_set(node->cmd_vector, &no_exec_timeout_cmd_vtysh);
	vector_set(node->cmd_vector, &no_vty_access_class_cmd_vtysh);
	vector_set(node->cmd_vector, &no_vty_ipv6_access_class_cmd_vtysh);
	vector_set(node->cmd_vector, &no_vty_login_cmd_vtysh);
	vector_set(node->cmd_vector, &vty_access_class_cmd_vtysh);
	vector_set(node->cmd_vector, &vty_ipv6_access_class_cmd_vtysh);
	vector_set(node->cmd_vector, &vty_login_cmd_vtysh);
}
